CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, config TEXT NOT NULL, health TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS scan_runs (id TEXT PRIMARY KEY, status TEXT NOT NULL, started TEXT NOT NULL, finished TEXT, heartbeat REAL NOT NULL, cancel INTEGER NOT NULL DEFAULT 0, mode TEXT NOT NULL, roster TEXT NOT NULL, progress TEXT NOT NULL DEFAULT '{}', metrics TEXT NOT NULL DEFAULT '{}', error TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_scan ON scan_runs((1)) WHERE status='running';
CREATE TABLE IF NOT EXISTS source_runs (run_id TEXT NOT NULL REFERENCES scan_runs(id), source_id TEXT NOT NULL, status TEXT NOT NULL, diagnostics TEXT NOT NULL, PRIMARY KEY(run_id,source_id));
CREATE TABLE IF NOT EXISTS opportunities (id TEXT PRIMARY KEY, canonical_url TEXT NOT NULL UNIQUE, first_seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), fingerprint TEXT NOT NULL, data TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(opportunity_id,fingerprint));
CREATE INDEX IF NOT EXISTS version_opportunity ON versions(opportunity_id);
CREATE TABLE IF NOT EXISTS evidence (version_id TEXT NOT NULL REFERENCES versions(id), field TEXT NOT NULL, url TEXT NOT NULL, excerpt TEXT NOT NULL, retrieved TEXT NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS candidates (run_id TEXT NOT NULL, source_id TEXT NOT NULL, opportunity_id TEXT NOT NULL, version_id TEXT NOT NULL REFERENCES versions(id), provenance TEXT NOT NULL, PRIMARY KEY(run_id,source_id,opportunity_id));
CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY REFERENCES scan_runs(id), published TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS membership (snapshot_id TEXT NOT NULL REFERENCES snapshots(id), opportunity_id TEXT NOT NULL REFERENCES opportunities(id), version_id TEXT NOT NULL REFERENCES versions(id), last_seen TEXT NOT NULL, stale INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(snapshot_id,opportunity_id));
CREATE INDEX IF NOT EXISTS membership_version ON membership(version_id);
CREATE TABLE IF NOT EXISTS publication (id INTEGER PRIMARY KEY CHECK(id=1), snapshot_id TEXT REFERENCES snapshots(id));
CREATE TABLE IF NOT EXISTS item_state (opportunity_id TEXT PRIMARY KEY REFERENCES opportunities(id), bookmarked INTEGER NOT NULL DEFAULT 0, dismissed INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, opportunity_id TEXT, type TEXT NOT NULL, title TEXT NOT NULL, created TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS saved_views (id TEXT PRIMARY KEY, name TEXT NOT NULL, filters TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fetch_cache (url TEXT PRIMARY KEY, etag TEXT, modified TEXT, body TEXT NOT NULL, content_type TEXT NOT NULL, content_hash TEXT NOT NULL, fetched TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schedule (id INTEGER PRIMARY KEY CHECK(id=1), next_run TEXT, worker_heartbeat TEXT);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'needs_review', notes TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS scans_started ON scan_runs(started DESC);
CREATE INDEX IF NOT EXISTS alerts_created ON alerts(created DESC);
